#[derive(Debug, Clone, Copy)]
pub struct Token {
    pub kind: TokenKind,
    span: Span,
}
impl Token {
    pub fn new(terminal_id: ids::TerminalId, span: Span) -> Token {
        Token {
            kind: token_kind(terminal_id),
            span,
        }
    }
    pub fn as_parse_tree<'a>(&self) -> ParseTree<'a> {
        ParseTree::Token(*self)
    }
    pub fn span(&self) -> Span {
        self.span
    }
}
fn token_kind(terminal_id: ids::TerminalId) -> TokenKind {
    match terminal_id {
        // Direction
        ids::TerminalId(0) => TokenKind::T0,
        // Hex
        ids::TerminalId(1) => TokenKind::T1,
        // Float
        ids::TerminalId(2) => TokenKind::T2,
        // Name
        ids::TerminalId(3) => TokenKind::T3,
        // Reserved
        ids::TerminalId(4) => TokenKind::T4,
        // WS
        ids::TerminalId(5) => TokenKind::T5,
        // i"select"
        ids::TerminalId(6) => TokenKind::T6,
        // ","
        ids::TerminalId(7) => TokenKind::T7,
        // i"from"
        ids::TerminalId(8) => TokenKind::T8,
        // "end"
        ids::TerminalId(9) => TokenKind::T9,
        // i"order"
        ids::TerminalId(10) => TokenKind::T10,
        // i"by"
        ids::TerminalId(11) => TokenKind::T11,
        // i"limit"
        ids::TerminalId(12) => TokenKind::T12,
        _ => unreachable!("Unknown TerminalId: {:?}", terminal_id),
    }
}
pub struct IgnoreCaseGrammarParseTreeBuilder<'a> {
    pub arena: &'a arena::Arena,
}
impl<'a> IgnoreCaseGrammarParseTreeBuilder<'a> {
    pub fn new(tree_arena: &'a arena::Arena) -> Self {
        Self { arena: tree_arena }
    }
    fn ambiguity_node(
        &self,
        parent: ids::NonterminalId,
        alternatives: &'a [ParseTree<'a>],
    ) -> ParseTree<'a> {
        match parent {
            grammar::QUERY => ParseTree::Query(self.arena.alloc(Query::Amb(alternatives))),
            grammar::ORDER => ParseTree::Order(self.arena.alloc(Order::Amb(alternatives))),
            grammar::LIMIT => ParseTree::Limit(self.arena.alloc(Limit::Amb(alternatives))),
            grammar::PLUS_0 => ParseTree::Plus0(self.arena.alloc(Plus0::Amb(alternatives))),
            grammar::OPT_0 => ParseTree::Opt0(self.arena.alloc(Opt0::Amb(alternatives))),
            grammar::OPT_1 => ParseTree::Opt1(self.arena.alloc(Opt1::Amb(alternatives))),
            grammar::OPT_2 => ParseTree::Opt2(self.arena.alloc(Opt2::Amb(alternatives))),
            grammar::ALT_0 => ParseTree::Alt0(self.arena.alloc(Alt0::Amb(alternatives))),
            grammar::START_QUERY => self.start_ambiguity_node(grammar::QUERY, alternatives),
            grammar::START_ORDER => self.start_ambiguity_node(grammar::ORDER, alternatives),
            grammar::START_LIMIT => self.start_ambiguity_node(grammar::LIMIT, alternatives),
            _ => unreachable!("nonterminal cannot be ambiguous"),
        }
    }
    fn start_ambiguity_node(
        &self,
        inner: ids::NonterminalId,
        alternatives: &'a [ParseTree<'a>],
    ) -> ParseTree<'a> {
        let first = alternatives[0].unwrap_start();
        let inner_alternatives = self
            .arena
            .alloc_slice(alternatives.iter().map(|a| a.unwrap_start().node));
        ParseTree::Start(self.arena.alloc(Start {
            before: first.before,
            node: self.ambiguity_node(inner, inner_alternatives),
            after: first.after,
            span: first.span,
        }))
    }
}
impl<'a> parse_tree::ParseTreeBuilder<ParseTree<'a>> for IgnoreCaseGrammarParseTreeBuilder<'a> {
    fn new_nonterminal_node(
        &self,
        nonterminal_node: &sppf::NonterminalNode,
        children: &[ParseTree<'a>],
    ) -> ParseTree<'a> {
        let span = nonterminal_node.span;
        match nonterminal_node.return_slot {
            // Query = i"select" WS {Name ","}+ WS i"from" WS Name WS Order? WS Limit? WS "end"
            SlotId(13) => {
                let &[
                    lit_12,
                    ws_11,
                    limit,
                    ws_9,
                    order,
                    ws_7,
                    name_6,
                    ws_5,
                    lit_4,
                    ws_3,
                    names_2,
                    ws_1,
                    lit_0,
                ] = children
                else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Query(self.arena.alloc(Query::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    ws_1: ws_1.unwrap_token(),
                    names_2: names_2.unwrap_plus_0(),
                    ws_3: ws_3.unwrap_token(),
                    lit_4: lit_4.unwrap_token(),
                    ws_5: ws_5.unwrap_token(),
                    name_6: name_6.unwrap_token(),
                    ws_7: ws_7.unwrap_token(),
                    order: order.unwrap_opt_0(),
                    ws_9: ws_9.unwrap_token(),
                    limit: limit.unwrap_opt_1(),
                    ws_11: ws_11.unwrap_token(),
                    lit_12: lit_12.unwrap_token(),
                    span,
                }))
            }
            // Order = i"order" WS i"by" WS Name WS Direction?
            SlotId(21) => {
                let &[direction, ws_5, name, ws_3, lit_2, ws_1, lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Order(self.arena.alloc(Order::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    ws_1: ws_1.unwrap_token(),
                    lit_2: lit_2.unwrap_token(),
                    ws_3: ws_3.unwrap_token(),
                    name: name.unwrap_token(),
                    ws_5: ws_5.unwrap_token(),
                    direction: direction.unwrap_opt_2(),
                    span,
                }))
            }
            // Limit = i"limit" WS (Hex | Float)
            SlotId(25) => {
                let &[alt_0, ws, lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Limit(self.arena.alloc(Limit::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    ws: ws.unwrap_token(),
                    alt_0: alt_0.unwrap_alt_0(),
                    span,
                }))
            }
            // Plus_0 = {Name ","}+ WS "," WS Name
            SlotId(31) => {
                let &[name_4, ws_3, lit_2, ws_1, names_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus0(self.arena.alloc(Plus0::Alt0 {
                    names_0: names_0.unwrap_plus_0(),
                    ws_1: ws_1.unwrap_token(),
                    lit_2: lit_2.unwrap_token(),
                    ws_3: ws_3.unwrap_token(),
                    name_4: name_4.unwrap_token(),
                    span,
                }))
            }
            // Plus_0 = Name
            SlotId(33) => {
                let &[name] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus0(self.arena.alloc(Plus0::Alt1 {
                    name: name.unwrap_token(),
                    span,
                }))
            }
            // Opt_0 = Order
            SlotId(35) => {
                let &[order] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Opt0(self.arena.alloc(Opt0::Alt0 {
                    order: order.unwrap_order(),
                    span,
                }))
            }
            // Opt_0 =
            SlotId(36) => {
                let &[] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Opt0(self.arena.alloc(Opt0::Alt1 { span }))
            }
            // Opt_1 = Limit
            SlotId(38) => {
                let &[limit] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Opt1(self.arena.alloc(Opt1::Alt0 {
                    limit: limit.unwrap_limit(),
                    span,
                }))
            }
            // Opt_1 =
            SlotId(39) => {
                let &[] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Opt1(self.arena.alloc(Opt1::Alt1 { span }))
            }
            // Opt_2 = Direction
            SlotId(41) => {
                let &[direction] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Opt2(self.arena.alloc(Opt2::Alt0 {
                    direction: direction.unwrap_token(),
                    span,
                }))
            }
            // Opt_2 =
            SlotId(42) => {
                let &[] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Opt2(self.arena.alloc(Opt2::Alt1 { span }))
            }
            // Alt_0 = Hex
            SlotId(44) => {
                let &[hex] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Alt0(self.arena.alloc(Alt0::Alt0 {
                    hex: hex.unwrap_token(),
                    span,
                }))
            }
            // Alt_0 = Float
            SlotId(46) => {
                let &[float] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Alt0(self.arena.alloc(Alt0::Alt1 {
                    float: float.unwrap_token(),
                    span,
                }))
            }
            // The start nonterminals with layout
            SlotId(50) | SlotId(54) | SlotId(58) => {
                let &[after, node, before] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Start(self.arena.alloc(Start {
                    before: Some(before),
                    node,
                    after: Some(after),
                    span,
                }))
            }
            _ => unreachable!(),
        }
    }
    fn new_token(&self, terminal_node: &sppf::TerminalNode) -> ParseTree<'a> {
        ParseTree::Token(Token::new(terminal_node.terminal_id, terminal_node.span))
    }
    fn new_ambiguity_node(
        &self,
        parent: ids::NonterminalId,
        alternatives: Vec<ParseTree<'a>>,
    ) -> ParseTree<'a> {
        self.ambiguity_node(parent, self.arena.alloc_slice(alternatives))
    }
}
// The parse tree of a finished parse, from the nonterminal node that spans the input.
pub fn create_parse_tree<'a>(
    root_id: ids::SPPFNodeId,
    parser: &parser::IgnoreCaseGrammarParser,
    builder: &IgnoreCaseGrammarParseTreeBuilder<'a>,
) -> ParseTree<'a> {
    let iguana_runtime::sppf::SPPFNode::Nonterminal(root) =
        iguana_runtime::parser::Parser::sppf_node(parser, root_id)
    else {
        panic!("the SPPF root is not a nonterminal node")
    };
    match root.nonterminal_id {
        grammar::QUERY => ParseTree::Query(visit_sppf(root_id, parser, builder).unwrap_query()),
        grammar::ORDER => ParseTree::Order(visit_sppf(root_id, parser, builder).unwrap_order()),
        grammar::LIMIT => ParseTree::Limit(visit_sppf(root_id, parser, builder).unwrap_limit()),
        grammar::PLUS_0 => ParseTree::Plus0(visit_sppf(root_id, parser, builder).unwrap_plus_0()),
        grammar::OPT_0 => ParseTree::Opt0(visit_sppf(root_id, parser, builder).unwrap_opt_0()),
        grammar::OPT_1 => ParseTree::Opt1(visit_sppf(root_id, parser, builder).unwrap_opt_1()),
        grammar::OPT_2 => ParseTree::Opt2(visit_sppf(root_id, parser, builder).unwrap_opt_2()),
        grammar::ALT_0 => ParseTree::Alt0(visit_sppf(root_id, parser, builder).unwrap_alt_0()),
        grammar::START_QUERY | grammar::START_ORDER | grammar::START_LIMIT => {
            ParseTree::Start(visit_sppf(root_id, parser, builder).unwrap_start())
        }
        _ => panic!(),
    }
}
impl<'a> parse_tree::ParseTreeNode for ParseTree<'a> {
    fn child(&self, index: usize) -> Option<Self> {
        ParseTree::child(self, index)
    }
    fn child_count(&self) -> usize {
        ParseTree::child_count(self)
    }
    fn display_name(&self) -> &'static str {
        ParseTree::display_name(self)
    }
    fn span(&self) -> Span {
        ParseTree::span(self)
    }
    fn kind(&self) -> parse_tree::NodeKind {
        if self.is_amb() {
            parse_tree::NodeKind::Amb
        } else if matches!(self, ParseTree::Token(_)) {
            parse_tree::NodeKind::Token
        } else {
            parse_tree::NodeKind::Nonterminal
        }
    }
    fn node_id(&self) -> Option<usize> {
        ParseTree::node_id(self)
    }
    fn nonterminal_id(&self) -> Option<ids::NonterminalId> {
        ParseTree::nonterminal_id(self)
    }
    fn origin(&self) -> Option<Origin> {
        ParseTree::origin(self)
    }
}
